/* From Uiverse.io by vamsidevendrakumar - Tags: animation, card, hover, animated, hover effect, card flip, hoverme, card template, hover slide */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 200px;
  perspective: 1000px;
}

.__UIV_SCOPE__ .card-inner {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.999s;
}

.__UIV_SCOPE__ .card:hover .card-inner {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .card-front,
.__UIV_SCOPE__ .card-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
}

.__UIV_SCOPE__ .card-front {
  background-color: #6A2C70;
  color: #fff;
  display: flex;
  align-items: center;
  border: 10px solid #6A2C70;
  border-radius: 10px;
  justify-content: center;
  font-size: 24px;
  transform: rotateY(0deg);
}

.__UIV_SCOPE__ .card-back {
  background-color: #F08A5D;
  color: #fff;
  display: flex;
  align-items: center;
  border: 10px solid #F08A5D;
  border-radius: 10px;
  justify-content: center;
  font-size: 24px;
  transform: rotateY(180deg);
}
